package com.ptms.controller; import com.ptms.dto.*; import com.ptms.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/teams") public class TeamController{private final TeamService s;public TeamController(TeamService s){this.s=s;}@GetMapping public List<TeamDto>all(){return s.all();}@PostMapping public TeamDto save(@Valid @RequestBody TeamDto d){return s.save(d);}@PutMapping("/{id}") public TeamDto update(@PathVariable Long id,@Valid @RequestBody TeamDto d){return s.save(new TeamDto(id,d.name(),d.department(),d.description(),d.enabled()));}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);}}
